1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 40px 16px;
12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 520px; margin: 0 auto; }
17	  h1 { font-size: 28px; margin: 0 0 16px; }
18	  form { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 10px 12px;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 8px;
26	    background: #fff;
27	  }
28	  input[type="date"], select {
29	    padding: 10px 12px;
30	    font: inherit;
31	    border: 1px solid #d6d3d1;
32	    border-radius: 8px;
33	    background: #fff;
34	    color: inherit;
35	  }
36	  input[type="text"]:focus, input[type="date"]:focus, select:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
37	  button {
38	    font: inherit;
39	    border: 0;
40	    border-radius: 8px;
41	    cursor: pointer;
42	  }
43	  .add { padding: 10px 18px; background: #2563eb; color: #fff; }
44	  .add:hover { background: #1d4ed8; }
45	  ul { list-style: none; margin: 0; padding: 0; }
46	  li {
47	    display: flex;
48	    align-items: center;
49	    gap: 12px;
50	    padding: 10px 12px;
51	    margin-bottom: 8px;
52	    background: #fff;
53	    border: 1px solid #e7e5e4;
54	    border-radius: 8px;
55	  }
56	  .text { flex: 1; overflow-wrap: anywhere; }
57	  li input[type="checkbox"] { width: 18px; height: 18px; margin: 0; cursor: pointer; accent-color: #2563eb; }
58	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
59	  .due { font-size: 14px; color: #57534e; white-space: nowrap; }
60	  /* Priority is shown as a neutral text label only; no colour coding. */
61	  .priority { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; padding: 2px 6px; border-radius: 4px; white-space: nowrap; background: #f5f5f4; color: #57534e; }
62	  li[data-overdue="true"] { border-color: #f87171; }
63	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
64	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
65	  .filters button { padding: 6px 12px; background: transparent; color: #44403c; border: 1px solid #d6d3d1; }
66	  .filters button:hover { background: #e7e5e4; }
67	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
68	  .delete { padding: 6px 10px; background: transparent; color: #b91c1c; }
69	  .delete:hover { background: #fee2e2; }
70	  .empty { color: #78716c; text-align: center; padding: 16px 0; }
71	</style>
72	</head>
73	<body>
74	<main>
75	  <h1>Todos</h1>
76	  <form id="todo-form">
77	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
78	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
79	    <select data-testid="todo-priority" aria-label="Priority">
80	      <option value="low">Low</option>
81	      <option value="med" selected>Med</option>
82	      <option value="high">High</option>
83	    </select>
84	    <button type="submit" class="add" data-testid="todo-add">Add</button>
85	  </form>
86	  <div class="filters" role="group" aria-label="Filter todos">
87	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
88	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
89	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
90	  </div>
91	  <ul data-testid="todo-list"></ul>
92	  <p class="empty" hidden>No todos yet.</p>
93	</main>
94	<script>
95	(function () {
96	  var STORAGE_KEY = 'todos';
97	  var form = document.getElementById('todo-form');
98	  var input = document.querySelector('[data-testid="todo-input"]');
99	  var dueInput = document.querySelector('[data-testid="todo-due"]');
100	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
101	  var list = document.querySelector('[data-testid="todo-list"]');
102	  var empty = document.querySelector('.empty');
103	  var filterButtons = document.querySelectorAll('[data-filter]');
104	
105	  var PRIORITIES = ['low', 'med', 'high'];
106	  var DEFAULT_PRIORITY = 'med';
107	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
108	
109	  function normalizePriority(p) {
110	    return PRIORITIES.indexOf(p) !== -1 ? p : DEFAULT_PRIORITY;
111	  }
112	
113	  function load() {
114	    try {
115	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
116	      if (!Array.isArray(data)) return [];
117	      // Todos saved before priorities existed default to "med".
118	      data.forEach(function (t) { t.priority = normalizePriority(t.priority); });
119	      return data;
120	    } catch (e) {
121	      return [];
122	    }
123	  }
124	
125	  function save() {
126	    try {
127	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
128	    } catch (e) {
129	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
130	    }
131	  }
132	
133	  function makeId() {
134	    if (window.crypto && typeof crypto.randomUUID === 'function') {
135	      return crypto.randomUUID();
136	    }
137	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
138	  }
139	
140	  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
141	  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
142	  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
143	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
144	
145	  function pad(n) { return (n < 10 ? '0' : '') + n; }
146	
147	  function todayLocal() {
148	    var d = new Date();
149	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
150	  }
151	
152	  // Overdue: due date strictly before today's local date. Due today is never overdue.
153	  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
154	  function isOverdue(todo, today) {
155	    return !!todo.due && todo.due < today;
156	  }
157	
158	  function formatDue(due) {
159	    var parts = due.split('-');
160	    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
161	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
162	  }
163	
164	  var todos = load();
165	  var filter = 'all';
166	  var renderedDay = null;
167	
168	  // Ordering rule (project decision): active todos first, completed todos below.
169	  // Within each group, sort by priority (high, med, low); within the same
170	  // priority, keep insertion order (oldest first). `todos` is stored in
171	  // insertion order, and the index tiebreak keeps the sort stable.
172	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
173	
174	  function byPriority(group) {
175	    return group
176	      .map(function (t, i) { return { todo: t, index: i }; })
177	      .sort(function (a, b) {
178	        return (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) || (a.index - b.index);
179	      })
180	      .map(function (entry) { return entry.todo; });
181	  }
182	
183	  function visibleTodos() {
184	    var active = byPriority(todos.filter(function (t) { return !t.completed; }));
185	    var completed = byPriority(todos.filter(function (t) { return t.completed; }));
186	    if (filter === 'active') return active;
187	    if (filter === 'completed') return completed;
188	    return active.concat(completed);
189	  }
190	
191	  function render() {
192	    list.textContent = '';
193	    var visible = visibleTodos();
194	    var today = todayLocal();
195	    renderedDay = today;
196	    visible.forEach(function (todo) {
197	      var li = document.createElement('li');
198	      li.setAttribute('data-testid', 'todo-item');
199	      li.setAttribute('data-id', todo.id);
200	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
201	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
202	      li.setAttribute('data-priority', todo.priority);
203	
204	      var toggle = document.createElement('input');
205	      toggle.type = 'checkbox';
206	      toggle.checked = !!todo.completed;
207	      toggle.setAttribute('data-testid', 'todo-toggle');
208	      toggle.setAttribute('aria-label', 'Mark complete');
209	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
210	
211	      var text = document.createElement('span');
212	      text.className = 'text';
213	      text.setAttribute('data-testid', 'todo-text');
214	      text.textContent = todo.text;
215	
216	      var del = document.createElement('button');
217	      del.type = 'button';
218	      del.className = 'delete';
219	      del.setAttribute('data-testid', 'todo-delete');
220	      del.setAttribute('aria-label', 'Delete todo');
221	      del.textContent = 'Delete';
222	      del.addEventListener('click', function () { remove(todo.id); });
223	
224	      var priority = document.createElement('span');
225	      priority.className = 'priority';
226	      priority.setAttribute('data-testid', 'todo-priority-label');
227	      priority.textContent = PRIORITY_LABELS[todo.priority];
228	
229	      li.appendChild(toggle);
230	      li.appendChild(text);
231	      li.appendChild(priority);
232	      if (todo.due) {
233	        var due = document.createElement('time');
234	        due.className = 'due';
235	        due.setAttribute('data-testid', 'todo-due-date');
236	        due.setAttribute('datetime', todo.due);
237	        due.textContent = 'Due ' + formatDue(todo.due);
238	        li.appendChild(due);
239	      }
240	      li.appendChild(del);
241	      list.appendChild(li);
242	    });
243	    empty.textContent = todos.length === 0 ? 'No todos yet.'
244	      : filter === 'active' ? 'No active todos.'
245	      : 'No completed todos.';
246	    empty.hidden = visible.length > 0;
247	    filterButtons.forEach(function (btn) {
248	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
249	    });
250	  }
251	
252	  function add(text, due, priority) {
253	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: normalizePriority(priority) });
254	    save();
255	    render();
256	  }
257	
258	  function remove(id) {
259	    todos = todos.filter(function (t) { return t.id !== id; });
260	    save();
261	    render();
262	  }
263	
264	  function setCompleted(id, completed) {
265	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
266	    save();
267	    render();
268	  }
269	
270	  filterButtons.forEach(function (btn) {
271	    btn.addEventListener('click', function () {
272	      filter = btn.getAttribute('data-filter');
273	      render();
274	    });
275	  });
276	
277	  form.addEventListener('submit', function (e) {
278	    e.preventDefault();
279	    var text = input.value.trim();
280	    if (!text) return;
281	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
282	    add(text, due, priorityInput.value);
283	    input.value = '';
284	    dueInput.value = '';
285	    priorityInput.value = DEFAULT_PRIORITY;
286	    input.focus();
287	  });
288	
289	  render();
290	
291	  // Overdue status changes at local midnight; re-render when the day rolls over.
292	  setInterval(function () {
293	    if (todayLocal() !== renderedDay) render();
294	  }, 30000);
295	})();
296	</script>
297	</body>
298	</html>
